package migrations

import (
	"math/big"

	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/vm"
	"github.com/ethereum/go-ethereum/log"
	"github.com/ethereum/go-ethereum/params"
)

type SunsetMigration struct {
	block *big.Int

	soulDropAddress common.Address
}

func NewSunsetMigration(config *params.ChainConfig) *SunsetMigration {
	if config.SystemContracts == nil || config.SunsetBlock == nil {
		return &SunsetMigration{}
	}

	return &SunsetMigration{
		block:           config.SunsetBlock,
		soulDropAddress: config.SystemContracts.SoulDrop,
	}
}

func (m *SunsetMigration) Block() *big.Int {
	return m.block
}

func (m *SunsetMigration) Name() string {
	return "sunset"
}

func (m *SunsetMigration) Execute(stateDB vm.StateDB) {
	if m.soulDropAddress == (common.Address{}) {
		log.Crit("invalid config: system contracts cannot be located at zero address")
	}

	// The purpose of this migration is making SoulDrop reward rates changeable without hardforks.
	// Until now reward percents by hold level have been fixed in the contract (percentByHoldLevel mapping,
	// initialised in constructor and adjusted by Cassiopeia hardfork), so every rate change required a hardfork.
	// The new SoulDrop version lets the contract owner schedule rate changes on-chain
	// (addRateChange, setRateChangePercent, removeRateChange) with a notice period for users:
	// a rate change is a timestamp with a full set of percents for every hold level,
	// and each reward period uses percents of the last rate change before its end (or percentByHoldLevel if there is none).
	// It also adds withdraw of the contract balance to the contract owner.
	// Migration consists of SoulDrop contract's bytecode update only:
	// - storage layout is kept (new variables are appended after existing ones), so claim timestamps, withholdings
	//   and percents set by Cassiopeia hardfork stay valid and rewards are calculated the same way until the first rate change;
	// - constructor is not executed on code replacement, so percentByHoldLevel keeps its on-chain values;
	// - balance and nonce of the contract are not affected.
	// Contract's code can be found at https://github.com/whitebit-exchange/soul-ecosystem-contracts/blob/main/contracts/drops/SoulDrop.sol

	// Updating SoulDrop contract's code (located at 0x0000000000000000000000000000000000001001 on mainnet).
	stateDB.SetCode(m.soulDropAddress, common.Hex2Bytes(""))
}
